work_dispatch_source:
proc state_work_dispatch_proc {} {
		global state_log state_shell prod_failurecount current_workplace current_worktask current_workitem current_workclass
		global current_digpos idletimeout current_occupation current_worklist current_plan
		global errorInfo

		if {$state_log} {log "[get_objname this] passing state code WORK_DISPATCH"}
		if {$state_shell} {print "[get_objname this] passing state code WORK_DISPATCH"}
		set current_occupation "work"
		set idletimeout 0

		if { [llength $current_worklist] == 0 } {
			set current_workplace 0
			state_trigger this work_idle
			return
		}
		set current_workdelay 2
		set currenttask [lindex $current_worklist 0]

		set evalerrMsg ""
		set evalresult 0
		if { [catch { set evalresult [eval $currenttask] } evalerrMsg ] } {
			log "Tasklist error in tasklist:$evalerrMsg"
			log " info:$errorInfo"
			if {$current_workplace != 0 && $current_workplace != "dig"} {
				log " Workplace: [get_objname $current_workplace]"
			}
			log " Current task: '$currenttask'"
			log " List:$current_worklist"
		}

		if { ![string is boolean $evalresult] || $evalresult == "" } {
			log "Tasklist warning: '$currenttask' returned '$evalresult' no boolean !!!"
		} else {
			if { $evalresult } {
				set prod_failurecount 0
				set current_worklist [lreplace $current_worklist 0 0]
				if {$current_workplace != 0 && $current_workplace != "dig"} {
					call_method $current_workplace prod_progress
				}
				return
			} else {

				if { $current_plan == "sparetime" } {
					state_triggerfresh this sparetime_dispatch
					return
				}
				incr prod_failurecount
				if {$prod_failurecount < 5} {
					state_disable this
					action this wait $current_workdelay {state_enable this}
				} else {
					set prod_failurecount 0
					set current_worklist [lreplace $current_worklist 0 0]
					state_triggerfresh this work_idle
				}
				return
			}
		}
	}

work_idle_source:
proc state_work_idle_proc {} {
		global state_log state_shell idletimeout current_workplace current_time_plan current_plan current_occupation
		global current_muetze_ref muetzen_counter muetzen_counter_start current_muetze_name muetzen_counter work_strike
		global sparetime_is_on

		if {$state_log} {log "[get_objname this] passing state code WORK_IDLE"}
		if {$state_shell} {print "[get_objname this] passing state code WORK_IDLE"}


		prod_gnome_state this idle

		incr idletimeout

		set current_occupation "idle"
		if { $idletimeout > 3 } {

			if {[act_when_idle]} {return}
		}
		if { $idletimeout > 5 } {
			if { [get_remaining_sparetime this] > 0.0 } {

				state_enable this
				state_triggerfresh this sparetime_dispatch
				return
			} elseif {$sparetime_is_on} {
				sparetime_state_end
			}
		}
		if { $idletimeout >10 } {
			if {$work_strike} {

				 state_triggerfresh this strike
			}
			if { [get_gnomeposition this] == 0 } {
				if {rand()<0.25} {

					state_triggerfresh this prodfill_dispatch
				}
			} else {
				if {[get_gnomeposition this]&&[get_prodautoschedule this]&&![walk_down_from_wall]} {return}
			}
		}

		if {$muetzen_counter < 0} {
			if {![get_prodautoschedule this]} {
                if {[call_method this get_nameofmuetze fight] != $current_muetze_name} {
					prod_change_muetze fight
					set muetzen_counter $muetzen_counter_start
				}
			} else {
				if {$idletimeout > 10 && $current_plan == "work"} {
					if {[call_method this get_nameofmuetze arbeitslos] != $current_muetze_name} {
						prod_change_muetze arbeitslos
						set muetzen_counter $muetzen_counter_start
					}
				}
			}
		}
		incr muetzen_counter -1

		set_idle_anim
		state_disable this
		action this wait 1 {state_enable this}
	}

rotate_source:
proc rotate_toangle {angle {anim ""}} {
	state_disable this;
	if {$anim==""} {
		action this rotate $angle {state_enable this}
	} else {
		action this rotate "$angle $anim" {state_enable this}
	}
	return true
}

stop_prod_source:
proc stop_prod {{toolchange 1}} {
	global current_workplace current_worklist reprod_actionlock walkfail_tasks
	global last_disturb sparetime_talkevents myref event_repeat

    beam_back
	set event_repeat 0
	if {[gettime]-$last_disturb>5} {
		switch [state_get this] {
			"sparetime_dispatch" {
				global stt_dst_spare current_occupation
				add_attrib this atr_Mood $stt_dst_spare
				lappend sparetime_talkevents wis
				if {[lsearch {eat fun slp} $current_occupation]!=-1} {sparetime_${current_occupation}_end}
			}
			"reprod" {global stt_dst_sex;add_attrib this atr_Mood $stt_dst_sex;lappend sparetime_talkevents ubr}
			"interaction" {global stt_dst_talk;add_attrib this atr_Mood $stt_dst_talk;lappend sparetime_talkevents ubt}
			"work_dispatch" {global stt_dst_work;add_attrib this atr_Mood $stt_dst_work;lappend sparetime_talkevents ubw}
			default {global stt_dst_idle;add_attrib this atr_Mood $stt_dst_idle}
		}
		set last_disturb [gettime]
	}

	set reprod_actionlock 0
	unlock_item
	foreach item [inv_list this] {
		set objtp [get_objtype $item]
		if {[lsearch {production elevator energy store protection} $objtp]!=-1} {
			set_prod_unpack $item 0
		}
	}
	dig_resetid this
	placelock_rem $myref
	placelock_rem [expr $myref + 65536]
	enable_auto_fanim
	dig_endanim
	sparetime_reset_clothes
	if {$toolchange} {change_tool 0; change_tool 0 1}
	set walkfail_tasks ""

	if { $current_workplace != 0 }	{
		if { $current_workplace != "dig" } {

			set tsklist [call_method $current_workplace stop_prod_tasklist [get_ref this]]
			foreach itm $tsklist {
				tasklist_add this $itm
			}
		}
		set current_workplace 0
	}
	set current_worklist ""
	set_particlesource this 1 0
}

check_in_source:
proc sparetime_check_in {placeref {meth 0}} {
	global sparetime_current_place sparetime_current_place_ref sparetime_seat sparetime_reservation
	set sparetime_reservation 0
	if {$sparetime_current_place_ref} {
		if {[obj_valid $sparetime_current_place_ref]} {
			prod_guest guestremove $sparetime_current_place_ref [get_ref this]
			prod_guest resetorder $sparetime_current_place_ref $sparetime_seat
		}
		set sparetime_current_place_ref 0
		set sparetime_current_place 0
	}
	if {$placeref} {
		if {$meth} {
			if {$meth==-1} {
				set seat [call_method $placeref get_random_seat]


			} else {
				set seat $meth
			}
		} else {
			set seat [prod_guest guestfree $placeref]
		}
		if {$seat != -1} {
			set sparetime_seat $seat

			prod_guest guestset $placeref $seat [get_ref this]

			prod_guest resetorder $placeref $seat
			set sparetime_current_place_ref $placeref
			set sparetime_current_place [get_objclass $placeref]
			return 1
		}
	}
	return 0
}

place_find_source:
proc sparetime_place_find {} {
	global sparetime_recent_places reprod_partner sparetime_avoid_place
	global stt_maxsearch_range spt_favplaces spt_place_desire spt_placefind_counter
	set max_search_range [sparetime_searchrange]
	set half_search_range [expr {$max_search_range*0.5}]
	set plist [sparetime this queryrect fun -$max_search_range -$half_search_range $max_search_range $half_search_range]
	if {$plist!=""} {

		set qplist [list]
		set fplist [list]
		incr spt_placefind_counter
		if {($spt_placefind_counter%5)==0} {
			set found 0
		} else {
			set found 1
		}
		foreach place $plist {
			if {[get_prod_pack $place]} {continue}
			if {$place==[lindex $sparetime_avoid_place 0]} {
				if {[gettime]-[lindex $sparetime_avoid_place 1]<50} {
					continue
				} else {
					set sparetime_avoid_place {0 0.0}
				}
			}
			if {[call_method $place get_inactive]} {continue}
			set placename [sparetime_translate_name [get_objclass $place] cv]
			if {!$found&&[prod_guest guestfree $place]==-1} {
				log "no seat free at $place"
				set placefail 1
			} elseif {$placename=="pub"&&[get_prod_materialneed $place]} {
				set placefail 2
			} else {
				set placefail 0
			}
			set pathcosts [expr {abs([get_posx this]-[get_posx $place])+abs([get_posy this]-[get_posy $place])*3.0}]
			if {$pathcosts<15||[check_method [get_objclass $place] reserve_seat]==0} {
				if {![call_method $place ask_for_seat]} {
					if {[call_method $place ask_for_reserve]} {
						set pathcosts [expr {10-$pathcosts}]
						set reserve 1
					} else {log "[get_objname this] no reservation possible ($place)";continue}
				} else {
					set reserve 0
				}
			} else {
				set reserve 1
			}
			log "pl: pc $pathcosts, afs [call_method $place ask_for_seat], afr [call_method $place ask_for_reserve] $reserve"
			set da [expr {$spt_place_desire*0.2}]
			set da [expr {$da+(1-$da)*0.05*[lcount $sparetime_recent_places $placename]}]
			if {$reprod_partner&&[obj_valid $reprod_partner]} {
				if {$place == [call_method $reprod_partner get_sparetime_place]} {
					set pathcosts [expr {$pathcosts*0.5}]
					set da [expr {$da*0.5}]
				}
			}
			if {[lsearch $spt_favplaces $placename]!=-1} {set da [expr {$da * 2.0}]}
			set jm [expr {1-(1-($pathcosts*$pathcosts)/($stt_maxsearch_range*$stt_maxsearch_range))*(1-$da)}]
			if {$placefail} {
				lappend fplist [list $place $jm $placename $placefail]
			} else {
				lappend qplist [list $place $jm $da $reserve [call_method $place ask_seat_cnt]]
			}
			set found 1
		}
		if {$qplist==""} {
			if {$fplist!=""} {
				set bestfull [lindex [lsort -index 1 -real $fplist] 0]
				if {[lindex $bestfull 3]<2} {
					set reason "[string index [lindex $bestfull 2] 0]fl"
				} else {
					set reason "pnb"
				}
				sparetime_place_fail $reason
			}
			return ""
		}
		return [lindex [lsort -index 1 -real $qplist] 0]
	}
	return ""
}
